    /// The identity map on `Vector`: a `Vector` with one open `Vector` slot.
    #[inline(always)]
    pub fn slot() -> Vector<(Vector,), T> {
        Vector { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

