impl<T: gx::Real> Vector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = t0 - t1;
        let t5 = t4 - t2;
        let t6 = t5 - t3;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (23 mul, 12 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Vector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = t0 * t0;
        let t5 = t0 * t1;
        let t6 = t0 * t2;
        let t7 = t0 * t3;
        let t8 = t1 * t1;
        let t9 = t1 * t2;
        let t10 = t1 * t3;
        let t11 = t2 * t2;
        let t12 = t2 * t3;
        let t13 = t3 * t3;
        let t14 = t4 + t8;
        let t15 = t11 + t14;
        let t16 = t13 + t15;
        let t17 = t9 + t10;
        let t18 = t12 + t17;
        let t19 = t18 - t5;
        let t20 = t19 - t6;
        let t21 = t20 - t7;
        let t22 = t21 * T::from_i64(2);
        let t23 = t16 + t22;
        let t24 = t23.recip();
        let t25 = t0 * t24;
        let t26 = t1 * t24;
        let t27 = t2 * t24;
        let t28 = t3 * t24;
        let t29 = t25 - t26;
        let t30 = t29 - t27;
        let t31 = t30 - t28;
        let t32 = x[0] * t31;
        let t33 = x[1] * t31;
        let t34 = x[2] * t31;
        let t35 = x[3] * t31;
        Vector::from_coeffs([t32, t33, t34, t35])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[2];
        let p3 = x[3] * x[3];
        let p4 = p0 - p1;
        let p5 = p4 - p2;
        let p6 = p5 - p3;
        let s0 = (p6).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Vector::from_coeffs([t0, t1, t2, t3]))
    }

}

#[doc = "A bivector: an electromagnetic field, or the generator of a Lorentz transformation. `e10, e20, e30` are the boosts (electric part), `e23, e31, e12` the rotations (magnetic part)."]
///
/// Blades, in coefficient order: `[e10, e20, e30, e23, e31, e12]`.
///
/// `S` lists the open slots: `Bivector` (that is, `Bivector<()>`) is a value, `Bivector<(A,)>` a
/// linear map from `A`, `Bivector<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Bivector<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 6],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Bivector<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Bivector<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Bivector<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Bivector<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Bivector");
        for (b, c) in <Bivector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Bivector {
    const N: usize = 6;
    const NAME: &'static str = "Bivector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e10", "e20", "e30", "e23", "e31", "e12"];
    type Arr<X: gx::Elem> = [X; 6];
    type Mv<S: gx::Slots, T: gx::Coef> = Bivector<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(f: impl FnMut(usize) -> X) -> [X; 6] {
        core::array::from_fn(f)
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 6], f: impl FnMut(&X) -> Y) -> [Y; 6] {
        a.each_ref().map(f)
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 6],
        b: &[Y; 6],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 6] {
        core::array::from_fn(|i| f(&a[i], &b[i]))
    }
}

