        let p2 = x[2] * x[2];
        let p3 = x[3] * x[3];
        let p4 = x[4] * x[4];
        let p5 = x[5] * x[5];
        let p6 = x[0] * x[3];
        let p7 = x[1] * x[4];
        let p8 = x[2] * x[5];
