        let p10 = p5 + p9;
        let p11 = p10 - p0;
        let p12 = p11 - p1;
        let p13 = p12 - p2;
        let p14 = p6 + p7;
        let p15 = p8 + p14;
        let p16 = p15 * T::from_i64(2);
        let [s0, s1] = gx::study::rsqrt(-1, p13, p16);
        let t0 = x[0] * s0;
        let t1 = x[3] * s1;
        let t2 = x[1] * s0;
        let t3 = x[4] * s1;
        let t4 = x[2] * s0;
        let t5 = x[5] * s1;
        let t6 = x[0] * s1;
        let t7 = x[3] * s0;
        let t8 = x[1] * s1;
        let t9 = x[4] * s0;
        let t10 = x[2] * s1;
        let t11 = x[5] * s0;
        let t12 = t0 + t1;
        let t13 = t2 + t3;
        let t14 = t4 + t5;
        let t15 = t7 - t6;
        let t16 = t9 - t8;
        let t17 = t11 - t10;
