impl<T: gx::Real> Pseudoscalar<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = -t0;
        t1
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (4 mul, 0 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Pseudoscalar<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t1 * t3;
        let t5 = -t4;
        Pseudoscalar::from_coeffs([t5])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = -p0;
        let s0 = (p1).abs().sqrt().recip();
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Pseudoscalar::from_coeffs([t0]))
    }

}

