impl<T: gx::Real> Multivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = x[4] * x[4];
        let t5 = x[5] * x[5];
        let t6 = x[6] * x[6];
        let t7 = x[7] * x[7];
        let t8 = x[8] * x[8];
        let t9 = x[9] * x[9];
        let t10 = x[10] * x[10];
        let t11 = x[11] * x[11];
        let t12 = x[12] * x[12];
        let t13 = x[13] * x[13];
        let t14 = x[14] * x[14];
        let t15 = x[15] * x[15];
        let t16 = t0 + t1;
        let t17 = t8 + t16;
        let t18 = t9 + t17;
        let t19 = t10 + t18;
        let t20 = t12 + t19;
        let t21 = t13 + t20;
        let t22 = t14 + t21;
        let t23 = t22 - t2;
        let t24 = t23 - t3;
        let t25 = t24 - t4;
        let t26 = t25 - t5;
        let t27 = t26 - t6;
        let t28 = t27 - t7;
        let t29 = t28 - t11;
        let t30 = t29 - t15;
        t30
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

